-- Name: COLUMN uom_uom.factor; Type: COMMENT; Schema: public; Owner: magpora_user
--

COMMENT ON COLUMN public.uom_uom.factor IS 'Ratio';


--
-- Name: COLUMN uom_uom.rounding; Type: COMMENT; Schema: public; Owner: magpora_user
--

COMMENT ON COLUMN public.uom_uom.rounding IS 'Rounding Precision';


