 .h3, .h4, .h5, .h6{margin-bottom: 0.5rem; font-weight: 500; line-height: 1.2;}h1, .h1{font-size: 2.5rem;}h2, .h2{font-size: 2rem;}h3, .h3{font-size: 1.75rem;}h4, .h4{font-size: 1.5rem;}h5, .h5{font-size: 1.25rem;}h6, .h6{font-size: 1rem;}p, span, strong, em{line-height: 1.5;}span.o_force_ltr{display: inline;}.o_force_ltr, .o_field_phone{unicode-bidi: embed; direction: ltr;}.border-black td, .border-black th{border-top: 1px solid black !important;}.table-sm > thead > tr > th{border-bottom: none !important;}.table-sm > tbody > tr{page-break-inside: avoid !important; border-top: none !important;}.zero_min_height{min-height: 0px !important;}.jumbotron, .panel, .carousel, section{page-break-inside: avoid;}.d-print-none{display: none;}.o_bold{font-weight: bolder;}.o_italic{font-style: italic;}.o_underline{text-decoration: underline;}div#total{page-break-inside: avoid;}div#total table tr.o_subtotal td, div#total table tr.o_total td{border-top: 1px solid black !important;}div#total table tr.o_subtotal.o_border_bottom td, div#total table tr.o_total.o_border_bottom td{border-bottom: 1px solid black !important;}table thead.o_black_border tr th{border-bottom: 2px solid black !important;}ol{margin-left: 40px; padding-left: 0;}ul .o_checklist > li{list-style: none; position: relative; margin-left: 20px;}ul .o_checklist > li:not(.oe-nested):before{content: ''; position: absolute; left: -20px; display: block; height: 14px; width: 14px; top: 1px; border: 1px solid; cursor: pointer;}ul .o_checklist > li.o_checked:after{content: "\n"; transition: opacity .5s; position: absolute; left: -18px; top: -1px; opacity: 1;}.col-auto{-webkit-box-flex: 1 !important;}.footer .row{-webkit-box-flex: 1 !important;}.footer .col-lg-3{-webkit-box-flex: 0; -webkit-flex: 0 0 auto; flex: 0 0 auto; -webkit-box-flex: 1 !important; width: 25%;}.footer .col-lg-4{-webkit-box-flex: 0; -webkit-flex: 0 0 auto; flex: 0 0 auto; -webkit-box-flex: 1 !important; width: 33.33333333%;}.footer .col-lg-6{-webkit-box-flex